<?php

declare( strict_types=1 );

namespace VocaSync\Tests;

use PHPUnit\Framework\TestCase;
use VocaSync\Tokenizer\SpokenForm;

/**
 * Asserts the PHP tokenizer reproduces the canonical TypeScript tokenizer
 * (`@vocasync/astro`) byte-for-byte, using fixtures generated by
 * `scripts/gen-tokenizer-fixtures.ts`. Regenerate fixtures whenever the TS
 * tokenizer changes; a diff here means the port has drifted.
 */
final class SpokenFormParityTest extends TestCase {

	/**
	 * @return array<string, array{0: array<string, mixed>}>
	 */
	public static function fixtureProvider(): array {
		$path = dirname( __DIR__ ) . '/fixtures/tokenizer/english.json';
		$json = file_get_contents( $path );
		if ( false === $json ) {
			self::fail( "Missing fixtures: $path (run `bun run scripts/gen-tokenizer-fixtures.ts`)" );
		}
		$fixtures = json_decode( $json, true );
		$cases    = array();
		foreach ( $fixtures as $i => $fixture ) {
			$label           = sprintf( '#%d %s', $i, self::describe( $fixture['input'] ) );
			$cases[ $label ] = array( $fixture );
		}
		return $cases;
	}

	private static function describe( string $input ): string {
		$short = mb_substr( $input, 0, 32 );
		return '' === $short ? '<empty>' : $short;
	}

	/**
	 * @dataProvider fixtureProvider
	 * @param array{input:string, expand:string, strip:string, normalised:string, tokenCount:int} $fixture
	 */
	public function test_parity( array $fixture ): void {
		$input = $fixture['input'];

		$this->assertSame(
			$fixture['expand'],
			SpokenForm::expand_spoken_forms( $input ),
			'expand_spoken_forms diverged'
		);
		$this->assertSame(
			$fixture['strip'],
			SpokenForm::strip_for_alignment( $input ),
			'strip_for_alignment diverged'
		);
		$this->assertSame(
			$fixture['normalised'],
			SpokenForm::strip_for_alignment( SpokenForm::expand_spoken_forms( $input ) ),
			'composed strip(expand()) diverged'
		);
		$this->assertSame(
			$fixture['tokenCount'],
			SpokenForm::token_count( $input, SpokenForm::MODE_ENGLISH ),
			'token_count diverged'
		);
	}

	public function test_language_modes(): void {
		$this->assertSame( SpokenForm::MODE_ENGLISH, SpokenForm::mode_for_language( 'en' ) );
		$this->assertSame( SpokenForm::MODE_LATIN, SpokenForm::mode_for_language( 'fr' ) );
		$this->assertSame( SpokenForm::MODE_LATIN, SpokenForm::mode_for_language( 'de' ) );
		$this->assertSame( SpokenForm::MODE_UNSUPPORTED, SpokenForm::mode_for_language( 'ru' ) );
		$this->assertSame( SpokenForm::MODE_UNSUPPORTED, SpokenForm::mode_for_language( 'ja' ) );
		$this->assertSame( SpokenForm::MODE_UNSUPPORTED, SpokenForm::mode_for_language( 'zh' ) );

		$this->assertTrue( SpokenForm::is_supported_language( 'pt' ) );
		$this->assertFalse( SpokenForm::is_supported_language( 'uk' ) );
	}

	public function test_latin_mode_skips_number_expansion(): void {
		// Latin mode must NOT inject English number words.
		$pair = SpokenForm::pair( 'J\'ai payé 50 euros', SpokenForm::MODE_LATIN );
		$this->assertStringNotContainsString( 'fifty', $pair['speechtext'] );
		$this->assertStringContainsString( '50', $pair['speechtext'] );
		// Strip still produces alignment tokens for Latin text.
		$this->assertNotSame( '', $pair['normalisedSpeechtext'] );
	}
}
